import{_ as e,o,c as t,ae as c}from"./chunks/framework.B1emQgFv.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"Python/Web应用开发/测试技术知识点.md","filePath":"Python/Web应用开发/测试技术知识点.md"}'),r={name:"Python/Web应用开发/测试技术知识点.md"};function l(i,a,m,n,k,s){return o(),t("div",null,[...a[0]||(a[0]=[c('<h2 id="软件测试技术-mock" tabindex="-1">软件测试技术-mock <a class="header-anchor" href="#软件测试技术-mock" aria-label="Permalink to &quot;软件测试技术-mock&quot;">​</a></h2><h3 id="_1-mock-含义" tabindex="-1">1-mock 含义 <a class="header-anchor" href="#_1-mock-含义" aria-label="Permalink to &quot;1-mock 含义&quot;">​</a></h3><p>测试的对象一般称之为SUT(Software Under Test) mock 即模拟/仿真，SUT 的依赖（dependency）。换句话说，mock 的作用是模拟 SUT 依赖对象的行为。类似在汽车测试中的相关ECU 仿真。</p><h3 id="_2-mock-级别" tabindex="-1">2-mock 级别： <a class="header-anchor" href="#_2-mock-级别" aria-label="Permalink to &quot;2-mock 级别：&quot;">​</a></h3><p>（1）方法级别 mock：mock 的对象是一个函数调用，例如获取系统环境变量。</p><p>（2）类级别 mock：mock 的对象是一个类，例如一个 HTTP server。</p><p>（3）接口级别 mock：mock 的对象是一个 API 接口。</p><p>（4）服务级别 mock：mock 的对象是整个服务。比如前端工程师自测试时，可以讲后端整个服务都 mock 掉，这其实等同于将后端的所有接口都 mock。</p><h3 id="_3-mock-方式" tabindex="-1">3-mock 方式 <a class="header-anchor" href="#_3-mock-方式" aria-label="Permalink to &quot;3-mock 方式&quot;">​</a></h3><ul><li>APIs请求构造</li><li>本地配置</li><li>配置中心</li><li>反向代理</li><li>前向代理</li></ul><h4 id="参考连接" tabindex="-1">参考连接 <a class="header-anchor" href="#参考连接" aria-label="Permalink to &quot;参考连接&quot;">​</a></h4><p><img src="https://blog.csdn.net/g6U8W7p06dCO99fQ3/article/details/114324301" alt="mock 技术"></p>',12)])])}const h=e(r,[["render",l]]);export{d as __pageData,h as default};
